CustomField.formula:
if(And(Category_Website_Active__c, Category_Service_Retention_Active__c), 
	"**Both Website/Service Retention = 15pts**", 
	"Both Website/Service Retention = 15pts")&BR()&
if(And(Category_Website_Active__c, Category_Service_Retention_Active__c=false), 
	"**Website Active Only = 10pts**", 
	"Website Active Only = 10pts")&BR()&
if(And(Category_Website_Active__c=false, Category_Service_Retention_Active__c),
	"**Service Retention Only = 5pts**", 
	"Service Retention Only = 5pts")&BR()&
if(And(Category_Website_Active__c=false, Category_Service_Retention_Active__c=false), 
	"**Neither Website/Service Retention = 0pts**", 
	"Neither Website/Service Retention = 0pts")
